WITH session_summary AS (SELECT session_id, MAX(duration_sec) AS max_duration_sec, ROUND((100 * SUM(CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_purchase FROM web_events WHERE TO_DATE(event_time) >= '2025-04-01' GROUP BY session_id) SELECT s.started_at, ss.max_duration_sec, ss.pct_purchase FROM sessions s INNER JOIN session_summary ss ON s.id = ss.session_id WHERE ss.pct_purchase > 77;
